// AP Physics 1 review bank, Unit 1: Kinematics (topics 1.1 to 1.5). Multiple choice first, then two free-response questions (EDA, TBR).
import { graph } from "../../plot.js";
import { scene } from "../../diagrams.js";

const r = String.raw;
const SK = { skill: "u1" };
// Four labeled pictures as four sources, so the choices "Graph A" to "Graph D" can point at them.
const pics = (word, svgs) => svgs.map((s, i) => ({ title: `${word} ${"ABCD"[i]}`, blocks: [{ svg: s }] }));
// A qualitative graph with no numbers on the axes (shape only).
const qg = (o) => graph({ x: [0, 6], y: [-1, 6], step: 100, width: 220, height: 160, xname: "t", yname: "v", ...o });
// A small arrow picture: one arrow from the middle of a strip.
const arr = (dx, alt) => scene({ width: 300, height: 56, alt, items: [{ dot: { x: 150, y: 28 } }, { arrow: { from: [150, 28], to: [150 + dx, 28], kind: "plain" } }] });
const arr2 = (dx, dy, alt) => scene({ width: 150, height: 110, alt, items: [{ dot: { x: 75, y: 55 } }, { arrow: { from: [75, 55], to: [75 + dx, 55 + dy], kind: "plain" } }] });

// ---------- drawings ----------
const axisScene = scene({ width: 380, height: 180, alt: "A horizontal axis marked in meters from negative 4 to 8. Point P is at 6, point Q at negative 2, and point R at 1. One arrow runs from P to Q, and a second arrow runs from Q to R.",
  items: [
    { arrow: { from: [70, 60], to: [352, 60], kind: "plain" } }, { label: { x: 366, y: 56, text: "x" } },
    ...[-4, -2, 0, 2, 4, 6, 8].flatMap((p) => [{ line: { from: [170 + 20 * p, 55], to: [170 + 20 * p, 65] } }, { label: { x: 170 + 20 * p, y: 40, text: String(p).replace("-", "−") } }]),
    { label: { x: 230, y: 22, text: "position (m)" } },
    { dot: { x: 290, y: 60 } }, { dot: { x: 130, y: 60 } }, { dot: { x: 190, y: 60 } },
    { label: { x: 290, y: 76, text: "P" } }, { label: { x: 130, y: 76, text: "Q" } }, { label: { x: 190, y: 76, text: "R" } },
    { line: { from: [290, 60], to: [290, 112], dash: true } }, { line: { from: [130, 60], to: [130, 142], dash: true } }, { line: { from: [190, 60], to: [190, 142], dash: true } },
    { arrow: { from: [290, 112], to: [130, 112], kind: "plain" } }, { arrow: { from: [130, 142], to: [190, 142], kind: "plain" } },
  ] });
const velPair = scene({ width: 360, height: 110, alt: "Two arrows drawn from the same starting point. The arrow labeled v_i points right and is 80 pixels long. The arrow labeled v_f points left and is 40 pixels long, half as long.",
  items: [{ dot: { x: 200, y: 82 } }, { arrow: { from: [200, 82], to: [280, 82], kind: "velocity", label: "v_i" } }, { dot: { x: 200, y: 32 } }, { arrow: { from: [200, 32], to: [160, 32], kind: "velocity", label: "v_f" } }] });
const carScene = scene({ width: 360, height: 150, alt: "A car drawn on a road. A green velocity arrow labeled v points to the left. A red acceleration arrow labeled a also points to the left.",
  items: [{ ground: { from: [20, 30], to: [340, 30] } }, { rect: { x: 180, y: 52, w: 100, h: 34, label: "car" } }, { arrow: { from: [180, 100], to: [100, 100], kind: "velocity", label: "v" } }, { arrow: { from: [180, 126], to: [100, 126], kind: "force", label: "a" } }] });
const walkway = scene({ width: 400, height: 190, alt: "A moving walkway drawn as a long rectangle. The lower arrow points right and is labeled 1.5 m/s, the walkway velocity relative to the ground. A person stands on it with an arrow pointing left labeled 2.0 m/s, the person velocity relative to the walkway.",
  items: [{ ground: { from: [30, 30], to: [370, 30] } }, { rect: { x: 200, y: 48, w: 300, h: 18 } }, { circle: { x: 200, y: 76, r: 10 } }, { arrow: { from: [200, 110], to: [130, 110], kind: "velocity", label: "2.0 m/s", dy: 10 } }, { arrow: { from: [140, 150], to: [240, 150], kind: "velocity", label: "1.5 m/s", dy: 10 } }] });
const trainScene = scene({ width: 400, height: 190, alt: "A train drawn as a long rectangle on a track. The lower arrow points right and is labeled v, the train velocity relative to the ground. A passenger inside has an arrow pointing left labeled 0.40 v, the passenger velocity relative to the train.",
  items: [{ ground: { from: [30, 30], to: [370, 30] } }, { rect: { x: 200, y: 62, w: 320, h: 56 } }, { circle: { x: 200, y: 60, r: 10 } }, { arrow: { from: [200, 72], to: [150, 72], kind: "velocity", label: "0.40v", dy: 4, dx: -6 } }, { arrow: { from: [150, 130], to: [260, 130], kind: "velocity", label: "v", dy: 12 } }] });
// A motorcycle leaves a horizontal ramp (h = 44.1 m, 22 m/s, lands 66 m away): the drawing is not to scale.
const cliffPts = Array.from({ length: 31 }, (_, k) => { const s = k / 30; return [150 + 264 * s, 208 - 188 * s * s]; });
const cliff = scene({ width: 450, height: 250, alt: "A motorcycle leaves the end of a horizontal ramp at the top of a platform. A green arrow shows a launch velocity of 22 meters per second to the right. A curved path falls to level ground 44.1 meters below, and the horizontal distance to the landing point is marked R.",
  items: [{ ground: { from: [90, 20], to: [440, 20], depth: 5 } }, { poly: { points: [[90, 20], [90, 200], [150, 200], [150, 20]] } }, { rope: { points: cliffPts, cls: "d-rope" } },
    { circle: { x: 150, y: 208, r: 6 } }, { arrow: { from: [158, 226], to: [218, 226], kind: "velocity", label: "22 m/s" } },
    { line: { from: [70, 20], to: [70, 200], dash: true } }, { label: { x: 64, y: 110, text: "44.1 m", anchor: "end" } },
    { arrow: { from: [150, 6], to: [414, 6], kind: "plain" } }, { label: { x: 282, y: 36, text: "R" } }] });
const topPts = Array.from({ length: 41 }, (_, k) => { const s = -1 + k / 20; return [180 + 140 * s, 150 - 110 * s * s]; });
const arcScene = scene({ width: 360, height: 190, alt: "A curved path of a ball that rises, reaches a highest point T, and falls. A green arrow at T points horizontally to the right.",
  items: [{ ground: { from: [20, 30], to: [340, 30] } }, { rope: { points: topPts, cls: "d-rope" } }, { dot: { x: 180, y: 150 } }, { label: { x: 168, y: 168, text: "T", anchor: "end" } }, { arrow: { from: [180, 150], to: [240, 150], kind: "velocity", label: "v" } }] });
const lab = scene({ width: 400, height: 260, alt: "A ramp leads onto the top of a table, and a ball rolls off the right edge. The path of the ball curves down to the floor. The table height h is marked on the left side and the horizontal distance x from the edge to the landing point is marked along the floor.",
  items: [{ ground: { from: [40, 40], to: [380, 40] } }, { poly: { points: [[60, 40], [60, 170], [220, 170], [220, 40]] } }, { poly: { points: [[70, 170], [70, 218], [150, 176], [220, 176], [220, 170]] } },
    { circle: { x: 80, y: 224, r: 5 } },
    { rope: { points: Array.from({ length: 21 }, (_, k) => { const s = k / 20; return [224 + 130 * s, 184 - 144 * s * s]; }) } },
    { arrow: { from: [230, 196], to: [290, 196], kind: "velocity", label: "v_0" } },
    { line: { from: [40, 40], to: [40, 170], dash: true } }, { label: { x: 32, y: 105, text: "h", anchor: "end" } },
    { arrow: { from: [224, 22], to: [354, 22], kind: "plain" } }, { label: { x: 289, y: 10, text: "x" } }] });

// ---------- graph builders for the sets ----------
const droneX = (t) => 5 + 4 * Math.sin((Math.PI * t) / 5);
const droneGraph = graph({ x: [0, 10], y: [0, 10], step: { x: 1, y: 2 }, xname: "t (s)", yname: "x (m)", fns: [{ f: droneX }],
  dots: [[1, droneX(1), "closed"], [2.5, droneX(2.5), "closed"], [4, droneX(4), "closed"], [5, droneX(5), "closed"]],
  labels: [[0.6, 7.2, "A"], [2.9, 9.2, "B"], [4.25, 7.5, "C"], [5.25, 5.4, "D"]],
  alt: "Position versus time for a drone. The curve rises from 5 meters, peaks at 9 meters at 2.5 seconds, falls through 5 meters at 5 seconds with the steepest downward slope, and reaches a minimum of 1 meter at 7.5 seconds. Point A is at 1 second on the way up, B is the peak, C is at 4 seconds on the way down, and D is at 5 seconds." });
const cartV = graph({ x: [0, 9], y: [-5, 7], step: 1, xname: "t (s)", yname: "v (m/s)", segments: [[0, -4, 2, 0], [2, 0, 5, 6], [5, 6, 7, 6], [7, 6, 9, 0]],
  dots: [[0, -4, "closed"], [2, 0, "closed"], [5, 6, "closed"], [7, 6, "closed"], [9, 0, "closed"]],
  alt: "Velocity versus time for a cart. The line rises from negative 4 meters per second at 0 seconds to 0 at 2 seconds, rises to 6 meters per second at 5 seconds, stays at 6 until 7 seconds, and falls to 0 at 9 seconds." });
const trainV = graph({ x: [0, 6], y: [0, 13], step: 1, xname: "t (s)", yname: "v (m/s)", segments: [[0, 9, 6, 3], [0, 0, 6, 12]],
  labels: [[0.3, 9.6, "A"], [4.6, 10.2, "B"]],
  alt: "Velocity versus time for trains A and B. Train A starts at 9 meters per second and falls in a straight line to 3 meters per second at 6 seconds. Train B starts at 0 and rises in a straight line to 12 meters per second at 6 seconds. The lines cross at 3 seconds, at 6 meters per second." });
const bikeV = graph({ x: [0, 7], y: [-5, 5], step: 1, xname: "t (s)", yname: "v (m/s)", segments: [[0, 0, 2, 4], [2, 4, 4, 4], [4, 4, 5, 0], [5, 0, 7, -4]],
  alt: "Velocity versus time for a cyclist. The line rises from 0 to 4 meters per second at 2 seconds, stays at 4 until 4 seconds, falls to 0 at 5 seconds, and continues down to negative 4 meters per second at 7 seconds." });
const segX = graph({ x: [0, 5], y: [-4, 8], step: 1, xname: "t (s)", yname: "x (m)", segments: [[0, 0, 2, 6], [2, 6, 5, -3]], dots: [[0, 0, "closed"], [2, 6, "closed"], [5, -3, "closed"]],
  alt: "Position versus time for an object. The line rises from 0 at 0 seconds to 6 meters at 2 seconds, then falls in a straight line to negative 3 meters at 5 seconds." });
const stepX = graph({ x: [0, 6], y: [0, 10], step: 1, xname: "t (s)", yname: "x (m)", segments: [[0, 0, 2, 8], [2, 8, 4, 8], [4, 8, 6, 2]], dots: [[0, 0, "closed"], [2, 8, "closed"], [4, 8, "closed"], [6, 2, "closed"]],
  alt: "Position versus time for an object. The line rises from 0 at 0 seconds to 8 meters at 2 seconds, stays at 8 meters until 4 seconds, then falls to 2 meters at 6 seconds." });
const xParab = graph({ x: [0, 6], y: [0, 28], step: { x: 1, y: 4 }, xname: "t (s)", yname: "x (m)", fns: [{ f: (t) => (t <= 3 ? t * t : 9 + 6 * (t - 3)) }],
  alt: "Position versus time for a cart. From 0 to 3 seconds the curve bends upward from the origin to 9 meters, then continues as a straight line with a constant upward slope to 27 meters at 6 seconds." });
const tbrV = graph({ x: [0, 5], y: [-4, 7], step: 1, xname: "t (s)", yname: "v (m/s)", segments: [[0, 6, 3, -3], [3, -3, 5, -3]], dots: [[0, 6, "closed"], [3, -3, "closed"], [5, -3, "closed"]],
  alt: "Velocity versus time for a cart. The line falls straight from 6 meters per second at 0 seconds, crosses 0 at 2 seconds, and reaches negative 3 meters per second at 3 seconds. It then stays at negative 3 meters per second until 5 seconds." });

// Four-choice picture sets.
const sigmoid = (t) => 5.5 / (1 + Math.exp(-1.1 * (t - 4.5)));
const elevator = [
  qg({ x: [0, 9], y: [-1, 6], segments: [[0, 0, 3, 4], [3, 4, 6, 4], [6, 4, 6, 0]], alt: "Velocity versus time. The line rises to a constant value, stays level, then drops straight down to zero at once." }),
  qg({ x: [0, 9], y: [-1, 6], segments: [[0, 0, 2, 4], [2, 4, 7, 4], [7, 4, 9, 0]], alt: "Velocity versus time. The line rises steadily, stays level for a long stretch, then falls steadily to zero." }),
  qg({ x: [0, 9], y: [-1, 6], segments: [[0, 0, 4.5, 4], [4.5, 4, 9, 0]], alt: "Velocity versus time. The line rises steadily to a peak and falls steadily, with no level section." }),
  qg({ x: [0, 9], y: [-1, 6], fns: [{ f: sigmoid }], alt: "Velocity versus time. An S-shaped curve starts near zero, rises smoothly, and levels off at a high value without returning to zero." }),
];
const accGraphs = [
  qg({ x: [0, 6], y: [-1, 4], yname: "a", segments: [[0, 2, 3, 2], [3, 0, 6, 0]], dots: [[3, 2, "open"], [3, 0, "closed"]], alt: "Acceleration versus time. A level line at a positive value from 0 to 3 seconds, then a level line at zero from 3 to 6 seconds." }),
  qg({ x: [0, 6], y: [-1, 4], yname: "a", segments: [[0, 2, 6, 2]], alt: "Acceleration versus time. A level line at a positive value from 0 to 6 seconds." }),
  qg({ x: [0, 6], y: [-1, 4], yname: "a", segments: [[0, 0, 3, 3], [3, 3, 6, 3]], alt: "Acceleration versus time. A line rises from zero at 0 seconds to a positive value at 3 seconds, then stays level." }),
  qg({ x: [0, 6], y: [-1, 4], yname: "a", segments: [[0, 0, 3, 0], [3, 2, 6, 2]], dots: [[3, 0, "open"], [3, 2, "closed"]], alt: "Acceleration versus time. A level line at zero from 0 to 3 seconds, then a level line at a positive value from 3 to 6 seconds." }),
];
const lineX = [
  graph({ x: [0, 4], y: [-8, 16], step: 4, xname: "t", yname: "x (m)", width: 220, height: 170, segments: [[0, 8, 4, 16]], alt: "Position versus time. A straight line rises from 8 meters at 0 seconds to 16 meters at 4 seconds." }),
  graph({ x: [0, 4], y: [-8, 16], step: 4, xname: "t", yname: "x (m)", width: 220, height: 170, segments: [[0, 8, 4, 0]], alt: "Position versus time. A straight line falls from 8 meters at 0 seconds to 0 at 4 seconds." }),
  graph({ x: [0, 4], y: [-8, 16], step: 4, xname: "t", yname: "x (m)", width: 220, height: 170, segments: [[0, 0, 4, -8]], alt: "Position versus time. A straight line falls from 0 at 0 seconds to negative 8 meters at 4 seconds." }),
  graph({ x: [0, 4], y: [-8, 16], step: 4, xname: "t", yname: "x (m)", width: 220, height: 170, segments: [[0, 8, 4, 8]], alt: "Position versus time. A horizontal line at 8 meters from 0 to 4 seconds." }),
];
const speedG = [
  qg({ x: [0, 6], y: [-6, 6], yname: "speed", segments: [[0, 5, 3, 0], [3, 0, 6, 5]], alt: "Speed versus time. A V shape: the line falls from a positive value to zero at 3 seconds and rises back to the same value at 6 seconds." }),
  qg({ x: [0, 6], y: [-6, 6], yname: "speed", segments: [[0, 5, 6, -5]], alt: "Speed versus time. A single straight line falls from a positive value, crosses zero at 3 seconds, and reaches a negative value at 6 seconds." }),
  qg({ x: [0, 6], y: [-6, 6], yname: "speed", segments: [[0, 0, 3, 5], [3, 5, 6, 0]], alt: "Speed versus time. An upside-down V: the line rises from zero to a peak at 3 seconds and falls back to zero at 6 seconds." }),
  qg({ x: [0, 6], y: [-6, 6], yname: "speed", fns: [{ f: (t) => 5 - (4 * (t * (6 - t))) / 9 }], alt: "Speed versus time. A smooth U-shaped curve that starts at a positive value, dips to a small positive minimum at 3 seconds, and rises again." }),
];
const walkX = [
  qg({ x: [0, 9], y: [-1, 6], yname: "x", segments: [[0, 0, 3, 3], [3, 3, 5, 3], [5, 3, 9, 0]], alt: "Position versus time. The line rises, stays level, then falls back to zero with a gentler slope than the rise." }),
  qg({ x: [0, 9], y: [-1, 6], yname: "x", segments: [[0, 0, 3, 3], [3, 3, 5, 3], [5, 3, 7, 0]], alt: "Position versus time. The line rises, stays level, then falls back to zero with a steeper slope than the rise." }),
  qg({ x: [0, 9], y: [-1, 6], yname: "x", segments: [[0, 0, 3, 3], [3, 3, 5, 3], [5, 3, 7, 5]], alt: "Position versus time. The line rises, stays level, then rises again." }),
  qg({ x: [0, 9], y: [-1, 6], yname: "x", segments: [[0, 0, 3, 3], [3, 3, 5, 0]], alt: "Position versus time. The line rises, then falls back to zero with no level section." }),
];
const dvArrows = [arr(40, "An arrow from the middle pointing right, 40 pixels long."), arr(120, "An arrow from the middle pointing right, 120 pixels long."), arr(-120, "An arrow from the middle pointing left, 120 pixels long."), arr(-40, "An arrow from the middle pointing left, 40 pixels long.")];
const accArrows = [arr2(0, 45, "An arrow pointing straight up."), arr2(50, 0, "An arrow pointing right."), arr2(0, -45, "An arrow pointing straight down."), arr2(-35, -35, "An arrow pointing down and to the left at 45 degrees.")];

