  "p1r-u1-s05": { name: "Position of a cart", label: "Graph", intro: r`The graph shows the position of a cart on a straight track.`, sources: [{ title: "", blocks: [{ svg: stepX }] }] },
  "p1r-u1-s06": { name: "A car with two arrows", label: "Diagram", intro: r`At one instant, a car on a straight road has the velocity and acceleration shown.`, sources: [{ title: "", blocks: [{ svg: carScene }] }] },
  // ---- 1.3 ----
  "p1r-u1-s07": { name: "A drone on a line", label: "Graph", intro: r`A drone flies along a straight line. The graph shows its position $x$ as a function of time. Positive is to the right.`, sources: [{ title: "", blocks: [{ svg: droneGraph }] }] },
  "p1r-u1-s08": { name: "A lab cart", label: "Graph", intro: r`The graph shows the velocity of a lab cart on a straight track. The cart is at $x = 0$ at $t = 0$, and positive is to the right.`, sources: [{ title: "", blocks: [{ svg: cartV }] }] },
  "p1r-u1-s09": { name: "An elevator trip", label: "Graphs", intro: r`An elevator starts from rest at the ground floor. It speeds up at a constant rate, moves up at constant speed, and then slows at a constant rate until it stops at the top floor. Choose the graph of the elevator's velocity as a function of time.`, sources: pics("Graph", elevator) },
  "p1r-u1-s10": { name: "From position to acceleration", label: "Graphs", intro: r`The first graph shows the position of a cart on a track. Choose the graph of the cart's acceleration as a function of time for the same $6$ s.`,
    sources: [{ title: "Position of the cart", blocks: [{ svg: xParab }] }, ...pics("Graph", accGraphs)] },
  "p1r-u1-s11": { name: "A rolling ball", label: "Graphs", intro: r`A ball starts at $x = +8$ m and rolls at a constant speed of $2$ m/s in the negative direction. Choose the graph of the ball's position as a function of time.`, sources: pics("Graph", lineX) },
  "p1r-u1-s12": { name: "A ball tossed upward", label: "Graphs", intro: r`A ball is tossed straight up, reaches its highest point, and falls back to the height from which it was tossed. Air resistance is negligible. Choose the graph of the ball's speed as a function of time.`, sources: pics("Graph", speedG) },
  "p1r-u1-s13": { name: "A walk past a motion detector", label: "Graphs", intro: r`A student walks along a straight line away from a starting mark at a steady pace, stops for a few seconds, and then walks back to the mark at a faster steady pace. Choose the graph of the student's distance from the mark as a function of time.`, sources: pics("Graph", walkX) },
